namespace sv_344b1b6c168e41708afa3985629cd1a4.Services;

public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public List<Warehouse> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
    ];

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        if (OnWarehouseChanged is not null)
            await OnWarehouseChanged.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

public record Warehouse(string Id, string Name);

namespace sv_344b1b6c168e41708afa3985629cd1a4.Services;

public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastLowStockCount;

    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Fired when alert data is refreshed so all subscribers can update.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate varying results per warehouse
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to refresh and broadcast to all subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        _lastLowStockCount = await GetLowStockCountAsync(warehouseId);
        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    public void Dispose()
    {
        OnAlertCountChanged = null;
    }
}

