@using sv_344b1b6c168e41708afa3985629cd1a4.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" style="max-width: 250px;"
        @onchange="OnWarehouseSelected" value="@WarehouseState.CurrentWarehouseId">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task OnWarehouseSelected(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            await WarehouseState.SetWarehouseAsync(newId);
        }
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@using sv_344b1b6c168e41708afa3985629cd1a4.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@AlertService.LastLowStockCount</span>

@code {
    private string BadgeClass => AlertService.LastLowStockCount > 5 ? "bg-danger" : "bg-warning text-dark";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleWarehouseChanged()
    {
        // Refresh immediately when warehouse changes
        await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@page "/dashboard"
@using sv_344b1b6c168e41708afa3985629cd1a4.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @AlertTextClass">@AlertService.LastLowStockCount</p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Warehouse ID</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">@(_isPolling ? "🟢 Active" : "🔴 Stopped")</p>
            </div>
        </div>
    </div>
</div>

